select

from
tdd_member_log


        and mid = #{mid}



            and false
            and added >= #{start_ts,typeHandler=com.bunnyxt.tdd.typehandler.EpochSecondTypeHandler}



        and added <= #{end_ts,typeHandler=com.bunnyxt.tdd.typehandler.EpochSecondTypeHandler}


        and attr = #{attr}


        and position(lower(#{oldval}) in lower(oldval)) > 0


        and position(lower(#{newval}) in lower(newval)) > 0


order by tdd_member_log.added desc, id desc
limit
#{ps} offset #{offset}

select
count(1)
from
tdd_member_log


        and mid = #{mid}



            and false
            and added >= #{start_ts,typeHandler=com.bunnyxt.tdd.typehandler.EpochSecondTypeHandler}



